// QA-only acceptance gap probes: actual block WriteVar rejection and late ACK replay prevention.
use field_flow::{config::Config,domain::id,fixture::Fixture,infrastructure::{state::{self,State,StateTask},s7_int_pdu::{Session,Operation,Validated}},runtime::Runtime};
use std::{path::{Path,PathBuf},time::Duration};
use serde_json::{json,Value};
async fn open(c:&Config,dir:&Path,bin:&Path,new:bool)->(Runtime,State,StateTask){if new{state::init(dir,"execute",&c.instance_id).unwrap()}let(s,t)=State::open(dir,"execute",&c.instance_id,&id()).unwrap();let r=Runtime::start(c,dir,bin,s.clone()).unwrap();let end=tokio::time::Instant::now()+Duration::from_secs(4);while r.owners["plc_demo"].health().state!="ready"{assert!(tokio::time::Instant::now()<end);tokio::time::sleep(Duration::from_millis(3)).await;}(r,s,t)}
async fn iteration(c:&Config,r:&Runtime,s:&State)->field_flow::Result<()>{field_flow::app::demo01::iteration(&c.flows[0],&c.plcs[0],&field_flow::services::Http::new(&c.http).unwrap(),&r.owners["plc_demo"],s,&r.stop,&mut field_flow::domain::Clock::default()).await}
async fn close(r:Runtime,s:State,t:StateTask){assert!(r.shutdown(15000).await.is_err());drop(s);t.join().await.unwrap();}
fn readback()->[u8;16]{use rust_snap7::{S7Client,InternalParam as P,InternalParamValue as V};let c=S7Client::create();c.set_param(P::RemotePort,V::U16(31102)).unwrap();c.connect_to("127.0.0.1",0,1).unwrap();let mut s=Session::default();let mut result=[0;16];for o in (0..16).step_by(2){match s.exchange(&c,1,o as u32,Operation::Read).unwrap(){Validated::Read(v)=>result[o..o+2].copy_from_slice(&v.value().to_be_bytes()),_=>panic!()}}c.disconnect().unwrap();drop(c);result}
fn main(){let q=PathBuf::from(std::env::args().nth(1).unwrap());tokio::runtime::Builder::new_multi_thread().worker_threads(4).enable_all().build().unwrap().block_on(async{
let bin=q.join("rust-formal-target/debug/field-flow");let mut f=Fixture::start(&q.join("rust-formal-target/debug/ff-fixture")).unwrap();let mut rows=Vec::new();
for case in ["block-write","late-correct-repeat"]{let mut c=Config::load(Path::new("config/loopback.yaml")).unwrap();if case=="block-write"{c.flows[0].target.db_size_bytes=32;c.flows[0].target.byte_offset=15;}c.validate().unwrap();let dir=q.join(case);let(r,s,t)=open(&c,&dir,&bin,true).await;let pid=r.owners["plc_demo"].health().pid.unwrap();let before=f.snapshot();f.command(case,json!(42));if case!="block-write"{f.fault("corrupt:follow_correct");}let error=iteration(&c,&r,&s).await.unwrap_err();assert_eq!(state::inspect(&dir).unwrap()["counts"]["unknown"],1);f.fault("");for _ in 0..10{assert_eq!(iteration(&c,&r,&s).await.unwrap_err(),"target_unknown");}close(r,s,t).await;assert_eq!(unsafe{libc::kill(pid as i32,0)},-1);
let(r,s,t)=open(&c,&dir,&bin,false).await;for _ in 0..10{assert_eq!(iteration(&c,&r,&s).await.unwrap_err(),"target_unknown");}close(r,s,t).await;let mem=readback();let snap=f.snapshot();assert_eq!(snap["writes"].as_u64().unwrap()-before["writes"].as_u64().unwrap(),1);let applied=snap["applied"].as_u64().unwrap()-before["applied"].as_u64().unwrap();if case=="block-write"{assert_eq!(applied,0);assert_eq!(mem,[0xa5;16]);}else{assert_eq!(applied,1);assert_eq!(&mem[..2],&42i16.to_be_bytes());assert!(mem[2..].iter().all(|b|*b==0xa5));}rows.push(json!({"case":case,"error":error,"config":c,"old_driver_pid":pid,"old_pid_gone":true,"same_identity_rounds_before_restart":10,"same_identity_rounds_after_restart":10,"actual_WriteVar":1,"positive_native_write_ack":applied,"memory":mem,"store":dir,"state":state::inspect(&dir).unwrap()}));}
let protocol=f.snapshot();let native_pid=f.native_pid;f.close().unwrap();let report:Value=json!({"rows":rows,"protocol":protocol,"native_pid":native_pid,"native_exit":0,"fixture_joined":true,"ports_rebound":[31102,31103,31880]});std::fs::write(q.join("rust-extra.json"),serde_json::to_vec_pretty(&report).unwrap()).unwrap();println!("{}",report);
});}
